import { test } from 'node:test'
import assert from 'node:assert/strict'
// Compiled output is generated by yarn test.
// eslint-disable-next-line n/no-unpublished-import
import { UpdateActions } from '../dist/actions.js'
// eslint-disable-next-line n/no-unpublished-import
import { GetConfigFields } from '../dist/config.js'

test('MSC action dispatches separately and existing OSC actions remain available', async () => {
	let actions
	const osc = []
	const midi = []
	UpdateActions({
		setActionDefinitions(value) {
			actions = value
		},
		VistaClient: {
			async send(...args) {
				osc.push(args)
			},
		},
		sendMsc(options) {
			midi.push(options)
		},
	})
	const expected = [
		'custom_message',
		'actionGridButton',
		'gmFader',
		'playbackButton',
		'playbackFader',
		'spbPlay',
		'spbPauseBack',
		'spbPrev',
		'spbNext',
		'spbSkipToStart',
		'spbSkipToEnd',
		'softkey',
		'highlight',
		'tapTempo',
		'stopFX',
		'lampOff',
		'lampOn',
		'reset',
		'solo',
		'quickUpdate',
		'update',
		'clearAllFeatures',
		'clearClose',
		'closeClip',
		'clearProgrammer',
		'releaseAllFeatures',
		'armTimecode',
		'saveShow',
	]
	assert.deepEqual(
		Object.keys(actions)
			.filter((key) => key !== 'msc' && !key.startsWith('msc_'))
			.sort(),
		expected.sort(),
	)
	for (const command of ['go', 'stop', 'resume']) {
		await actions.msc.callback({ options: { command, cue: '34.5', cuelist: '12' } })
	}
	assert.equal(midi.length, 3)
	assert.equal(osc.length, 0)
	await actions.gmFader.callback({ options: { level: 50 } })
	await actions.custom_message.callback({ options: { address: '/test' } })
	assert.deepEqual(osc, [
		['/V3/console/EX/1/gmFader', ['0.5']],
		['/test', ['']],
	])
	assert.equal(midi.length, 3)
})
test('config defaults preserve OSC, make MSC opt-in and expose named ports', () => {
	const fields = GetConfigFields(['Vista'])
	const field = (id) => fields.find((item) => item.id === id)
	assert.equal(field('oscEnabled').default, true)
	assert.equal(field('mscEnabled').default, false)
	assert.equal(field('commandFormat').default, 1)
	assert.equal(field('deviceId').max, 127)
	assert.deepEqual(field('midiPort').choices[1], { id: 'Vista', label: 'Vista' })
})
